from fastapi import FastAPI, File, Form
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/form-then-file")
async def form_then_file(form_val: str = Form(...), file_val: bytes = File(...)):
    return {"form_val": form_val, "file_val": file_val}

@app.post("/file-then-form")
async def file_then_form(file_val: bytes = File(...), form_val: str = Form(...)):
    return {"form_val": form_val, "file_val": file_val}

client = TestClient(app)

def test_form_then_file():
    # This is the case that is reported to fail
    response = client.post(
        "/form-then-file",
        data={"form_val": "hello"},
        files={"file_val": b"world"}
    )
    print(f"Form then File response: {response.status_code}, {response.json()}")
    assert response.status_code == 200

def test_file_then_form():
    # This is the case that is reported to work
    response = client.post(
        "/file-then-form",
        data={"form_val": "hello"},
        files={"file_val": b"world"}
    )
    print(f"File then Form response: {response.status_code}, {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_form_then_file()
        print("test_form_then_file passed")
    except Exception as e:
        print(f"test_form_then_file failed: {e}")

    try:
        test_file_then_form()
        print("test_file_then_form passed")
    except Exception as e:
        print(f"test_file_then_form failed: {e}")

